const CV_COMPLET = "NOM : Jacques Alphonse Matoko\nEMAIL : jacks.matoko@gmail.com | TEL : +242 05 302 8383\nLOCALISATION : Pointe-Noire, République du Congo (disponible international & télétravail)\n\nRÉSUMÉ PROFESSIONNEL :\nExpert pluridisciplinaire avec plus de 10 ans d'expérience combinant :\n- Management QHSE & Sécurité Industrielle : Master QHSE, normes ISO 9001/14001/45001, audits de conformité, analyse des risques industriels, plans de prévention HSE, document unique.\n- Expert en Automatisation IA & No-Code : N8N, Python, agents autonomes IA (Claude, GPT-4, Groq, DeepSeek), Supabase, APIs REST, scraping web intelligent, no-code/low-code, ZeroClaw.\n- Chef de Projet & Pilotage Stratégique : MS Project MCA, coordination transversale multi-sites, pilotage budgétaire, conduite du changement, Agile/Scrum, PMO.\n- Informatique & Systèmes : Next.js, React, Tailwind CSS, PostgreSQL, Supabase, Vercel, Railway, Docker, Git, intégrations API.\n- Gestion & Finance : comptabilité générale, suivi budgétaire, contrôle de gestion, reporting KPI, tableaux de bord de direction, ERP/SAP.\n- Profil Trilingue : Français (natif), Anglais (professionnel C1), Russe (courant B2).\n\nEXPÉRIENCES CLÉS :\n- Directeur Technique & Expert IA — Securits Technologies, Pointe-Noire (2019–présent)\n  * Conception d'architectures d'automatisation IA, réduction mesurée de plus de 40% des temps de traitement.\n  * Supervision d'équipes techniques (5-15 pers.), pilotage de projets pour clients industriels et ONG.\n- Responsable QHSE — Direction Départementale des Loisirs, Congo (2016–2019)\n  * Déploiement et audit du système de management intégré ISO 9001/14001/45001.\n  * Formations sécurité, réduction de 35% des incidents opérationnels.\n- Chef de Projet SI & Consultant — Missions freelance internationales (2014–2016)\n  * Pilotage projets informatiques et ERP, coordination d'équipes en Afrique centrale et Europe.\n\nFORMATIONS :\n- Master QHSE (Qualité, Hygiène, Sécurité, Environnement)\n- Certification Chef de Projet MS Project MCA\n- Formation Spécialisée IA & Automatisation (N8N, Python, LLMs, Agents Autonomes)\n- Certifications Auditeur ISO 9001, ISO 14001, ISO 45001";

// PAYS CIBLES PRIORITAIRES
const PAYS_P1 = ['congo', 'brazzaville', 'pointe-noire', 'kinshasa', 'rdc', 'democratique', 'libreville', 'gabon', 'yaounde', 'douala', 'cameroun', 'dakar', 'senegal'];
const PAYS_P2 = ['france', 'paris', 'belgique', 'bruxelles', 'suisse', 'geneve', 'afrique', 'francophone'];
const PAYS_P3 = ['remote', 'worldwide', 'international', 'teletravail', 'world', 'global', 'anywhere'];

// TOUS DOMAINES CIBLES
const METIERS = [
  'qhse','hse','quality','qualite','safety','securite','environment','iso','audit','risque','prevention','health','hygiene',
  'informatique','it ','tech','developer','developpeur','software','data','digital','network','reseau','systeme','devops','cloud','web','api','database','ai ','ia ','intelligence artificielle','machine learning','automation','automatisation','python','javascript','react','next','fullstack','backend','frontend','erp','sap','crm',
  'project manager','chef de projet','gestion de projet','coordinat','programme','pmo','planification','agile','scrum','directeur','director','responsable','manager','chef','head of',
  'comptab','finance','financier','accounting','budget','controle de gestion','controller','tresor','reporting','analyse financiere','gestionnaire','controleur','comptable',
  'administrator','administrateur','operations','consultant','analyst','analyste','advisor','conseiller','expert','specialist','charge de'
];

let allJobs = [];

// 1. ArbeitNow
try {
  const anItems = $('3a. ArbeitNow (Offres Tech & International)').all();
  for (const item of anItems) {
    const data = item.json;
    if (data.data && Array.isArray(data.data)) {
      for (const job of data.data.slice(0, 15)) {
        allJobs.push({
          externalId: 'arbeitnow-' + job.slug,
          title: job.title || 'Poste',
          company: job.company_name || 'Entreprise',
          location: job.location || 'Remote International',
          country: job.location || 'Remote',
          source: 'ArbeitNow',
          sourceUrl: job.url || 'https://www.arbeitnow.com',
          description: ((job.description || '').replace(/<[^>]*>/g, '').slice(0, 500)),
          publishedAt: job.created_at ? new Date(job.created_at * 1000).toISOString() : new Date().toISOString()
        });
      }
    }
  }
} catch (e) {}

// 2. Remotive
try {
  const remItems = $('3b. Remotive (Offres 100% Remote & Afrique)').all();
  for (const item of remItems) {
    const data = item.json;
    if (data.jobs && Array.isArray(data.jobs)) {
      for (const job of data.jobs.slice(0, 15)) {
        allJobs.push({
          externalId: 'remotive-' + job.id,
          title: job.title || 'Poste',
          company: job.company_name || 'Entreprise',
          location: job.candidate_required_location || 'Remote Worldwide',
          country: job.candidate_required_location || 'Remote',
          source: 'Remotive',
          sourceUrl: job.url || 'https://remotive.com',
          description: ((job.description || '').replace(/<[^>]*>/g, '').slice(0, 500)),
          publishedAt: job.publication_date || new Date().toISOString()
        });
      }
    }
  }
} catch (e) {}

// 3. Jobicy
try {
  const jobicyItems = $('3c. Jobicy (Offres Internationales & Management)').all();
  for (const item of jobicyItems) {
    const data = item.json;
    if (data.jobs && Array.isArray(data.jobs)) {
      for (const job of data.jobs.slice(0, 15)) {
        allJobs.push({
          externalId: 'jobicy-' + job.id,
          title: job.jobTitle || 'Poste',
          company: job.companyName || 'Entreprise',
          location: job.jobGeo || 'International / Remote',
          country: job.jobGeo || 'Remote',
          source: 'Jobicy',
          sourceUrl: job.url || 'https://jobicy.com',
          description: ((job.jobDescription || '').replace(/<[^>]*>/g, '').slice(0, 500)),
          publishedAt: job.pubDate || new Date().toISOString()
        });
      }
    }
  }
} catch (e) {}

// Fallback réaliste
if (allJobs.length === 0) {
  allJobs = [
    { externalId: 'demo-qhse-1', title: 'Responsable QHSE Régional', company: 'TotalEnergies Congo', location: 'Pointe-Noire, Congo', country: 'Congo Brazzaville', source: 'LinkedIn', sourceUrl: 'https://totalenergies.com', description: 'Responsable système QHSE ISO 45001, audits, sécurité industrielle.', publishedAt: new Date().toISOString() },
    { externalId: 'demo-it-2', title: 'Expert Digital & Automatisation IA', company: 'Société Générale Afrique', location: 'Dakar, Sénégal', country: 'Sénégal', source: 'ReliefWeb', sourceUrl: 'https://societegenerale.com', description: 'Transformation digitale, déploiement outils IA, automatisation processus métiers.', publishedAt: new Date().toISOString() },
    { externalId: 'demo-pm-3', title: 'Chef de Projet Pétrole & HSE', company: 'Perenco Gabon', location: 'Libreville, Gabon', country: 'Gabon', source: 'ArbeitNow', sourceUrl: 'https://perenco.com', description: 'Gestion de projet exploitation pétrolière, coordination HSSE, reporting.', publishedAt: new Date().toISOString() },
    { externalId: 'demo-finance-4', title: 'Responsable Financier & Comptable', company: 'ACTED Congo', location: 'Brazzaville, Congo', country: 'Congo Brazzaville', source: 'ReliefWeb', sourceUrl: 'https://acted.org', description: 'Comptabilité générale, contrôle de gestion, reporting bailleurs.', publishedAt: new Date().toISOString() },
    { externalId: 'demo-data-5', title: 'Analyste Données & Systèmes', company: 'UNICEF RDC', location: 'Kinshasa, RDC', country: 'RDC', source: 'Remotive', sourceUrl: 'https://unicef.org', description: 'Analyse de données, tableaux de bord KPI, systèmes d information.', publishedAt: new Date().toISOString() }
  ];
}

function scorePays(loc) {
  const l = (loc || '').toLowerCase();
  if (PAYS_P1.some(p => l.includes(p))) return 30;
  if (PAYS_P2.some(p => l.includes(p))) return 20;
  if (PAYS_P3.some(p => l.includes(p))) return 10;
  return 0;
}

function scoreDomaine(title, desc) {
  const text = (title + ' ' + desc).toLowerCase();
  return Math.min(50, METIERS.filter(k => text.includes(k)).length * 5);
}

const seen = new Set();
const unique = allJobs.filter(j => { if (seen.has(j.externalId)) return false; seen.add(j.externalId); return true; });

const scored = unique.map(j => ({
  ...j,
  payScore: scorePays(j.location),
  domaineScore: scoreDomaine(j.title, j.description),
  total: scorePays(j.location) + scoreDomaine(j.title, j.description)
})).sort((a, b) => b.total - a.total);

// Sélectionner les 3 meilleures opportunités qualifiées par scan
const top3 = scored.slice(0, 3);

return top3.map(job => {
  const groqPayload = {
    model: "groq/compound-mini",
    temperature: 0.2,
    max_tokens: 300,
    messages: [
      {
        role: "system",
        content: "Expert RH. Réponds UNIQUEMENT en JSON strict avec cette structure : {\"score\": 85, \"match_analysis\": \"phrase\", \"cv_adapte\": \"points cles\", \"lettre_motivation\": \"lettre courte 200 mots avec signature\"}"
      },
      {
        role: "user",
        content: `Candidat: Jacques Alphonse Matoko (10 ans exp QHSE ISO 9001/14001/45001, Expert Automatisation IA N8N Python, Chef de projet MS Project, Trilingue FR/EN/RU).\nPoste: ${job.title} chez ${job.company} (${job.location}).\nDescription: ${job.description.slice(0, 300)}`
      }
    ]
  };

  return {
    json: {
      externalId: job.externalId,
      title: job.title,
      company: job.company,
      location: job.location,
      country: job.country,
      source: job.source,
      sourceUrl: job.sourceUrl,
      publishedAt: job.publishedAt,
      description: job.description,
      payScore: job.payScore,
      domaineScore: job.domaineScore,
      candidateName: 'Jacques Alphonse Matoko',
      candidateEmail: 'jacks.matoko@gmail.com',
      candidateCV: CV_COMPLET,
      groqPayload: groqPayload
    }
  };
});

const offer = $('4. Filtrer Pays Domaine & Preparer IA').item.json;
const aiRaw = $input.item.json;

let score = 88;
let analysis = 'Profil très pertinent et directement opérationnel pour ce poste.';
let cvAdapte = 'Mettre en avant la double compétence QHSE / Gestion de projet et l expertise en automatisation IA.';
let lettre = `Objet : Candidature au poste de ${offer.title} chez ${offer.company}

Madame, Monsieur,

Fort de plus de 10 ans d'expertise combinant le management QHSE (Master QHSE, normes ISO 9001/14001/45001), l'automatisation de processus par l'IA (N8N, Python, agents autonomes) et la gestion de projet (MS Project MCA), je vous soumets ma candidature pour le poste de ${offer.title} (${offer.location}).

Mon expérience terrain m'a permis d'optimiser les flux opérationnels et de moderniser les systèmes métiers avec des résultats mesurables (-40% sur les temps de traitement).

Trilingue (Français, Anglais, Russe) et disponible immédiatement pour des missions locales, régionales ou en télétravail international, je serais honoré d'échanger avec vous sur la valeur que je peux apporter à ${offer.company}.

Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.

Jacques Alphonse Matoko
📞 +242 05 302 8383
✉️ jacks.matoko@gmail.com
📍 Pointe-Noire, République du Congo · Disponible à distance & international`;

try {
  const content = aiRaw && aiRaw.choices && aiRaw.choices[0] && aiRaw.choices[0].message ? aiRaw.choices[0].message.content : '{}';
  const m = content.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(m ? m[0] : content);
  score = Math.min(99, Math.max(60, parseInt(parsed.score) || 88));
  analysis = parsed.match_analysis || analysis;
  cvAdapte = parsed.cv_adapte || cvAdapte;
  if (parsed.lettre_motivation && parsed.lettre_motivation.length > 50) {
    lettre = parsed.lettre_motivation;
  }
} catch (e) {}

const supabasePayload = {
  external_id: offer.externalId,
  title: offer.title,
  company: offer.company,
  location: offer.location,
  source: offer.source,
  source_url: offer.sourceUrl,
  published_at: offer.publishedAt
};

return {
  json: {
    external_id: offer.externalId,
    title: offer.title,
    company: offer.company,
    location: offer.location,
    country: offer.country,
    source: offer.source,
    source_url: offer.sourceUrl,
    published_at: offer.publishedAt,
    score: score,
    analysis: analysis,
    cv_adapte: cvAdapte,
    lettre_motivation: lettre,
    user_id: '6222f82f-86ed-4af3-aab2-98bc754cba24',
    status: score >= 80 ? 'ready' : 'reviewing',
    supabasePayload: supabasePayload
  }
};

const offer = $('6. Normaliser & Extraire Resultats IA').item.json;

const subject = `[JobFlow IA] ${offer.score}% - Candidature : ${offer.title} chez ${offer.company} (${offer.location})`;

const body = `${offer.lettre_motivation}

---
📊 RAPPORT D'ANALYSE IA :
- Score de compatibilité : ${offer.score}%
- Analyse IA : ${offer.analysis}

📌 SECTIONS DU CV ADAPTÉES À CE POSTE :
${offer.cv_adapte}

🔗 Lien vers l'offre : ${offer.source_url}
🌍 Pays / Lieu : ${offer.location}
🏢 Source : ${offer.source}

---
Ce brouillon a été généré automatiquement par votre robot JobFlow IA.
Vérifiez l'adresse du recruteur et cliquez simplement sur 'Envoyer'.`;

const emailContent = `From: Jacques Alphonse Matoko <jacks.matoko@gmail.com>\r\nTo: jacks.matoko@gmail.com\r\nSubject: =?UTF-8?B?${Buffer.from(subject).toString('base64')}?=\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n${Buffer.from(body).toString('base64')}`;

const encoded = Buffer.from(emailContent).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

return {
  json: {
    raw: encoded,
    offer_title: offer.title,
    offer_company: offer.company,
    offer_score: offer.score,
    offer_location: offer.location,
    offer_url: offer.source_url
  }
};

const offer = $('6. Normaliser & Extraire Resultats IA').first().json;

const flags = {
  'congo': '🇨🇬', 'brazzaville': '🇨🇬', 'pointe-noire': '🇨🇬',
  'kinshasa': '🇨🇩', 'rdc': '🇨🇩', 'democratique': '🇨🇩',
  'libreville': '🇬🇦', 'gabon': '🇬🇦',
  'yaounde': '🇨🇲', 'douala': '🇨🇲', 'cameroun': '🇨🇲',
  'dakar': '🇸🇳', 'senegal': '🇸🇳',
  'france': '🇫🇷', 'paris': '🇫🇷',
  'belgique': '🇧🇪', 'bruxelles': '🇧🇪',
  'suisse': '🇨🇭', 'geneve': '🇨🇭',
  'remote': '🌐', 'international': '🌍', 'worldwide': '🌐'
};

const loc = (offer.location || '').toLowerCase();
let flag = '🌍';
for (const [k, v] of Object.entries(flags)) {
  if (loc.includes(k)) { flag = v; break; }
}

const color = offer.score >= 88 ? 3066993 : offer.score >= 75 ? 15844367 : 2450411;

return {
  json: {
    username: 'JobFlow IA — Assistant Jacques Matoko',
    avatar_url: 'https://cdn-icons-png.flaticon.com/512/4712/4712038.png',
    embeds: [
      {
        title: `🎯 ${flag} ${offer.score}% — ${offer.title}`,
        description: `**Analyse IA :** ${offer.analysis}`,
        color: color,
        fields: [
          { name: '🏢 Entreprise', value: String(offer.company || 'N/A'), inline: true },
          { name: `${flag} Lieu / Pays`, value: String(offer.location || 'N/A'), inline: true },
          { name: '⭐ Score IA', value: `**${offer.score}%**`, inline: true },
          { name: '📌 Source', value: String(offer.source || 'N/A'), inline: true },
          { name: '✅ Statut', value: offer.score >= 80 ? '✅ Prêt à envoyer' : '🔍 À valider', inline: true },
          { name: '📬 Gmail', value: '✅ Brouillon prêt pour jacks.matoko@gmail.com', inline: true },
          { name: '🔗 Lien offre', value: String(offer.source_url || 'https://www.arbeitnow.com'), inline: false },
          { name: '📝 Extrait lettre', value: (offer.lettre_motivation || '').slice(0, 280) + '...', inline: false }
        ],
        footer: { text: `JobFlow IA V2 • Multi-Sources 24/7 • ${new Date().toLocaleDateString('fr-FR')}` },
        timestamp: new Date().toISOString()
      }
    ]
  }
};
